# Define the custom CUDA kernel for matrix multiplication with register blocking
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16
#define REG_BLOCK 2

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Each thread computes REG_BLOCK x REG_BLOCK elements
    int row_base = by * TILE_SIZE + ty;
    int col_base = bx * TILE_SIZE + tx;

    float sum[REG_BLOCK][REG_BLOCK] = {0};

    for (int k = 0; k < (N + TILE_SIZE - 1) / TILE_SIZE; k++) {
        // Load tiles into shared memory
        if (row_base < N && k * TILE_SIZE + tx < N) {
            As[ty][tx] = A[row_base * N + k * TILE_SIZE + tx];
        } else {
            As[ty][tx] = 0.0f;
        }

        if (col_base < N && k * TILE_SIZE + ty < N) {
            Bs[ty][tx] = B[(k * TILE_SIZE + ty) * N + col_base];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial products for register block
        for (int i = 0; i < TILE_SIZE; i++) {
            float a_reg = As[ty][i];
            float b_reg = Bs[i][tx];

            for (int ri = 0; ri < REG_BLOCK; ri++) {
                for (int rj = 0; rj < REG_BLOCK; rj++) {
                    if (row_base + ri * TILE_SIZE / REG_BLOCK < N && 
                        col_base + rj * TILE_SIZE / REG_BLOCK < N) {
                        sum[ri][rj] += a_reg * b_reg;
                    }
                }
            }
        }

        __syncthreads();
    }

    // Write results
    for (int ri = 0; ri < REG_BLOCK; ri++) {
        for (int rj = 0; rj < REG_BLOCK; rj++) {
            int row = row_base + ri * TILE_SIZE / REG_BLOCK;
            int col = col_base + rj * TILE_SIZE / REG_BLOCK;
            if (row < N && col < N) {
                C[row * N + col] = sum[ri][rj];
            }
        }
    }
}

